<?php
require_once __DIR__ . '/config/bootstrap.php';
$pageTitle='Your Bag — Ikki';$cart=$_SESSION['cart']??[];$items=[];$subtotal=0;
if($cart){$ids=array_values(array_filter(array_map('intval',array_keys($cart))));if($ids){$marks=implode(',',array_fill(0,count($ids),'?'));$st=db()->prepare("SELECT v.id,v.variant_name,v.price,v.stock_quantity,p.name,p.slug,(SELECT image_path FROM product_images WHERE product_id=p.id ORDER BY is_primary DESC,sort_order LIMIT 1) image_path FROM product_variants v JOIN products p ON p.id=v.product_id WHERE v.id IN ($marks) AND v.is_active=1 AND p.is_active=1");$st->execute($ids);foreach($st->fetchAll() as $row){$qty=min((int)$row['stock_quantity'],max(1,(int)$cart[$row['id']]));if($qty<1){unset($_SESSION['cart'][$row['id']]);continue;}$row['quantity']=$qty;$row['line_total']=$qty*(float)$row['price'];$subtotal+=$row['line_total'];$items[]=$row;}}}
require __DIR__.'/includes/header.php';
?>
<div class="page-wrap"><div class="page-intro"><span class="eyebrow">Your selection</span><h1 class="page-title">Your bag</h1></div><?php if(isset($_GET['added'])):?><div class="notice">Added to your bag.</div><?php endif; ?><?php if(!$items): ?><p class="muted">Your bag is waiting for a signature scent.</p><a class="btn" href="/shop.php">Explore the collection</a><?php else: ?><form method="post" action="/actions/cart-update.php"><?php echo csrf_field(); ?><div style="overflow-x:auto"><table class="cart-table"><thead><tr><th>Fragrance</th><th>Price</th><th>Qty</th><th>Total</th></tr></thead><tbody><?php foreach($items as $item): ?><tr><td><?= e($item['name']) ?><br><small class="muted"><?= e($item['variant_name']) ?></small></td><td><?= money($item['price']) ?></td><td><input style="max-width:75px" type="number" min="0" max="<?= (int)$item['stock_quantity'] ?>" name="qty[<?= (int)$item['id'] ?>]" value="<?= (int)$item['quantity'] ?>"></td><td><?= money($item['line_total']) ?></td></tr><?php endforeach; ?></tbody></table></div><p><button class="btn btn-outline" type="submit">Update bag</button></p></form><div style="max-width:360px;margin:35px 0 0 auto"><p>Subtotal <strong style="float:right"><?= money($subtotal) ?></strong></p><p class="muted">Delivery charges are confirmed at checkout.</p><a class="btn" href="/checkout.php">Continue to checkout</a></div><?php endif; ?></div>
<?php require __DIR__.'/includes/footer.php'; ?>
